SELECT product_id, CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END AS sale_cohort, MAX(sale_date) AS last_sale_date, ROUND(STDDEV(units), 2) AS stddev_units FROM store_sales WHERE product_id = 10 AND store_id = 1 GROUP BY product_id, CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY product_id, last_sale_date
